DROP TABLE IF EXISTS "public"."kst_jenis_kawasan";
DROP TABLE IF EXISTS "public"."nilai_data_lokasi";
DROP TABLE IF EXISTS "public"."kst_quick_filter";
DROP TABLE IF EXISTS "public"."kst_fokus_riset";
DROP TABLE IF EXISTS "public"."kst_lokasi";
DROP TABLE IF EXISTS "public"."kst_kabupaten_kota";
DROP TABLE IF EXISTS "public"."kst_provinsi";
DROP TABLE IF EXISTS "public"."label_data_lokasi";
DROP TABLE IF EXISTS "public"."users";
DROP TABLE IF EXISTS "public"."kst_galeri";
-- Table Definition
CREATE TABLE "public"."kst_jenis_kawasan" (
    "id" uuid NOT NULL,
    "nama" varchar(150) NOT NULL,
    "slug" varchar(150) NOT NULL,
    "deskripsi" text,
    "is_active" bool,
    "created_at" timestamp,
    "updated_at" timestamp,
    "parent_id" uuid,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."nilai_data_lokasi" (
    "id" uuid NOT NULL,
    "lokasi_id" uuid NOT NULL,
    "field_label_id" uuid NOT NULL,
    "value" text,
    "created_at" timestamp,
    "updated_at" timestamp,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."kst_quick_filter" (
    "id" uuid NOT NULL,
    "nama" varchar(150) NOT NULL,
    "slug" varchar(150) NOT NULL,
    "filter_data" json NOT NULL,
    "created_at" timestamp,
    "updated_at" timestamp,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."kst_fokus_riset" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "nama" varchar(100) NOT NULL,
    "slug" varchar(100) NOT NULL,
    "is_active" bool,
    "created_at" timestamp,
    "updated_at" timestamp,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."kst_lokasi" (
    "id" uuid NOT NULL,
    "nama" varchar(255) NOT NULL,
    "slug" varchar(255),
    "deskripsi" text,
    "jenis_kawasan_id" uuid,
    "pengelola" varchar(150) DEFAULT 'BRIN'::character varying,
    "status" varchar(50),
    "tahun_operasi" int4,
    "is_draft" bool,
    "provinsi_kode" varchar(10),
    "kabupaten_kota_kode" varchar(10),
    "alamat" text,
    "luas_ha" float8,
    "latitude" float8,
    "longitude" float8,
    "geom" geometry,
    "created_at" timestamp,
    "updated_at" timestamp,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."kst_kabupaten_kota" (
    "kode" varchar(10) NOT NULL,
    "province_kode" varchar(10) NOT NULL,
    "nama" varchar(150) NOT NULL,
    "tipe" varchar(20),
    "created_at" timestamptz DEFAULT now(),
    "updated_at" timestamptz DEFAULT now(),
    PRIMARY KEY ("kode")
);

-- Table Definition
CREATE TABLE "public"."kst_provinsi" (
    "kode" varchar(10) NOT NULL,
    "nama" varchar(100) NOT NULL,
    "created_at" timestamptz DEFAULT now(),
    "updated_at" timestamptz DEFAULT now(),
    PRIMARY KEY ("kode")
);

-- Table Definition
CREATE TABLE "public"."label_data_lokasi" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "nama" varchar(150) NOT NULL,
    "slug" varchar(150) NOT NULL,
    "placeholder" varchar(255),
    "icon" varchar(50) DEFAULT 'FileText'::character varying,
    "created_at" timestamptz DEFAULT now(),
    "updated_at" timestamptz DEFAULT now(),
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."users" (
    "id" uuid NOT NULL,
    "username" varchar(50) NOT NULL,
    "email" varchar(255),
    "hashed_password" varchar(255) NOT NULL,
    "full_name" varchar(255) NOT NULL,
    "role" varchar(50) NOT NULL,
    "is_active" int4 NOT NULL,
    "last_login_at" timestamptz,
    "created_at" timestamptz DEFAULT now(),
    "updated_at" timestamptz DEFAULT now(),
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."kst_galeri" (
    "id" uuid NOT NULL,
    "lokasi_id" uuid NOT NULL,
    "tipe" varchar(20) NOT NULL,
    "url" text NOT NULL,
    "created_at" timestamp,
    "updated_at" timestamp,
    PRIMARY KEY ("id")
);

