('5450a5a8-c77a-4445-a780-53c09bbf457b', '43aa0911-306b-41ce-97ef-4069a3dd5371', '907ea8fc-4406-43d3-8a03-200fe28472cb', '<p>Laboratorium Terpadu Riset Oseanografi A - F</p>', '2026-10-16 06:37:26.93573', '2026-10-16 06:37:26.93573'),
