('02b16488-e684-4887-a7cc-acf1abfee570', 'BRIDA Kab. Kolaka', 'brida-kab-kolaka', 'Badan Riset dan Inovasi Daerah (BRIDA) bertugas mengoordinasikan, menyinergikan, dan memfasilitasi riset serta inovasi di tingkat daerah guna mendukung pembangunan dan potensi daerah.', '08194a9a-24de-49fc-8790-167202f5a089', 'Pemerintah Daerah / BRIN', 'Aktif', NULL, f, '74', '74.01', 'WHWW+GFQ, Jl. Doktor Sutomo, Lamokato, Kec. Kolaka, Kabupaten Kolaka, Sulawesi Tenggara 93511', NULL, -4.121351, 121.692944, ST_GeomFromText('SRID=4326;POINT(121.692944 -4.121351)'), '2026-10-15 15:28:04.172299', '2026-10-16 05:37:53.76113'),
